  const radio=loadDynamicRuntime("Bidoo","antN"),radioAsset=new Float32Array(radio.memory.buffer,radio.rack_web_asset_buffer(),8);
  radioAsset.set([.5,-.5,1,-1,-.5,.5,-1,1]);radio.rack_web_commit_asset(4,2,48000);
