  const delayed=instantiate();oneTap(delayed);process(delayed,1);assert.equal(delayed.runtime.rack_web_get_output_channels(0),2);assert.deepEqual([read(delayed,0),read(delayed,1),read(delayed,2),read(delayed,1,1)],[1.25,10,2,0]);for(let block=0;block<374;block++)process(delayed);process(delayed,127);assert.equal(read(delayed,1,1,126),0);process(delayed,1);assert.deepEqual([read(delayed,0,1),read(delayed,1,1),read(delayed,2,1)],[2.25,10,7]);
  const muted=instantiate();oneTap(muted);muted.runtime.rack_web_set_param(12,0);for(let block=0;block<375;block++)process(muted);process(muted,1);assert.equal(read(muted,1,1),0);
  const tempo=instantiate();oneTap(tempo);tempo.runtime.rack_web_set_param(21,1);for(let block=0;block<187;block++)process(tempo);process(tempo,64);assert.equal(read(tempo,1,1,63),0);process(tempo,1);assert.equal(read(tempo,1,1),10);
  const wet=instantiate();oneTap(wet);process(wet);wet.runtime.rack_web_set_param(20,1);for(let block=0;block<3;block++)process(wet);wet.runtime.rack_web_set_param(20,0);process(wet);assert.equal(snapshot(wet).wetOnly,true);assert.equal(wet.runtime.rack_web_get_output_channels(0),1);assert.equal(wet.lights[0],1);
  const poly=instantiate();oneTap(poly);poly.runtime.rack_web_set_param(16,2);for(const port of[0,1,2])poly.runtime.rack_web_set_input_channels(port,2);setInput(poly,0,2.5,1);setInput(poly,1,10,1);setInput(poly,2,3,1);process(poly,1);assert.equal(poly.runtime.rack_web_get_output_channels(0),4);assert.deepEqual([read(poly,0,0),read(poly,0,1),read(poly,1,0),read(poly,1,1)],[1.25,2.5,10,10]);
