test("Valley sequencers, SIMD filters, synth voices, and embedded wavetable ROMs run from one official revision",()=>{
  const catalog=JSON.parse(fs.readFileSync(new URL("../public/dynamic-plugins/catalog.json",import.meta.url),"utf8")),commit="86f02e431136a7f5c96a872b99b7115b7e133e05",contracts={Topograph:[10,10,6,5,4194304],uGraph:[10,10,6,5,4194304],Feline:[17,12,3,0,16777216],Amalgam:[14,13,12,1,4194304],Interzone:[43,14,15,2,67108864],Dexter:[141,57,7,43,16777216],Terrorform:[51,29,8,16,33554432]},definitions={};for(const [model,contract] of Object.entries(contracts)){const definition=catalog.find(item=>item.key===`Valley/${model}`);assert.ok(definition,`${model} missing from catalog`);definitions[model]=definition;assert.equal(definition.localBuild.sourceCommit,commit);assert.equal(definition.runtime.strategy,"direct-rack-source-adapter");assert.deepEqual([definition.params.length,definition.inputs.length,definition.outputs.length,definition.lights,definition.runtime.initialMemory],contract)}assert.ok(definitions.Topograph.params.every(param=>param.position));assert.ok(definitions.uGraph.inputs.every(input=>input.position));assert.ok([...definitions.Dexter.params.filter(param=>!param.hidden),...definitions.Dexter.inputs.filter(input=>!input.hidden),...definitions.Dexter.outputs.filter(output=>!output.hidden)].every(control=>control.position));assert.equal(definitions.Amalgam.inputs[6].hidden,true);assert.equal(definitions.Interzone.inputs[9].hidden,true);assert.ok(fs.statSync(new URL("../public/dynamic-plugins/Valley/Dexter/module.wasm",import.meta.url)).size>1000000);
  const create=model=>{const definition=definitions[model],runtime=loadDynamicRuntime("Valley",model);for(const param of definition.params)runtime.rack_web_set_param(param.id,param.default);for(let output=0;output<definition.outputs.length;output++)runtime.rack_web_set_output_connected(output,1);return{definition,runtime,inputs:new Float32Array(runtime.memory.buffer,runtime.rack_web_input_buffer(),definition.inputs.length*16*128),outputs:new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),definition.outputs.length*16*128)}};
  for(const model of ["Topograph","uGraph"]){const {runtime,inputs,outputs}=create(model);for(const input of [0,9]){runtime.rack_web_set_input_connected(input,1);runtime.rack_web_set_input_channels(input,1)}let peak=0,nonzero=0;for(let block=0;block<64;block++){inputs.fill(0);for(let frame=0;frame<128;frame++)inputs[frame]=Math.sin((block*128+frame)*.04)*2;if(block%8===0)inputs.fill(10,9*128,9*128+2);runtime.rack_web_process(128,48000);for(const value of outputs){assert.ok(Number.isFinite(value));peak=Math.max(peak,Math.abs(value));nonzero+=Math.abs(value)>1e-6}}assert.equal(peak,10);assert.ok(nonzero>100)}
  {const {runtime,inputs,outputs}=create("Feline");runtime.rack_web_set_input_connected(0,1);runtime.rack_web_set_input_channels(0,1);let peak=0;for(let block=0;block<24;block++){for(let frame=0;frame<128;frame++)inputs[frame]=Math.sin((block*128+frame)*.03)*4;runtime.rack_web_process(128,48000);for(const value of outputs){assert.ok(Number.isFinite(value));peak=Math.max(peak,Math.abs(value))}}assert.ok(peak>1)}
  {const {runtime,inputs,outputs}=create("Amalgam");for(const input of [0,2]){runtime.rack_web_set_input_connected(input,1);runtime.rack_web_set_input_channels(input,1)}let peak=0;for(let block=0;block<16;block++){for(let frame=0;frame<128;frame++){inputs[frame]=Math.sin((block*128+frame)*.05)*3;inputs[2*128+frame]=Math.cos((block*128+frame)*.03)*2}runtime.rack_web_process(128,48000);for(const value of outputs){assert.ok(Number.isFinite(value));peak=Math.max(peak,Math.abs(value))}}assert.ok(peak>1)}
  {const {runtime,inputs,outputs}=create("Interzone");runtime.rack_web_set_input_connected(3,1);runtime.rack_web_set_input_channels(3,1);let peak=0;for(let block=0;block<24;block++){inputs.fill(10,3*128,4*128);runtime.rack_web_process(128,48000);for(const value of outputs){assert.ok(Number.isFinite(value));peak=Math.max(peak,Math.abs(value))}}assert.ok(peak>4&&peak<20)}
  for(const model of ["Dexter","Terrorform"]){const {runtime,outputs}=create(model);let peak=0,nonzero=0;for(let block=0;block<24;block++){runtime.rack_web_process(128,48000);for(const value of outputs){assert.ok(Number.isFinite(value));peak=Math.max(peak,Math.abs(value));nonzero+=Math.abs(value)>1e-6}}assert.ok(peak>4&&peak<20);assert.ok(nonzero>1000)}
});

test("Fundamental Wavetable VCO morphs a finite audio-rate table",()=>{
  const runtime=loadRuntime("fundamental-wtvco"),outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),128);
  assert.deepEqual([runtime.rack_web_param_count(),runtime.rack_web_input_count(),runtime.rack_web_output_count(),runtime.rack_web_light_count()],[7,4,1,5]);
  runtime.rack_web_set_param(3,.8);runtime.rack_web_process(128,48000);
  assert.ok(outputs.every(Number.isFinite));assert.ok(Math.max(...outputs)-Math.min(...outputs)>1);
});

test("Fundamental Wavetable VCO carries four pitch voices",()=>{
  const runtime=loadRuntime("fundamental-wtvco"),inputCount=runtime.rack_web_input_count();
  const inputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_input_buffer(),inputCount*16*128),outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),16*128);
  runtime.rack_web_set_polyphony(4);runtime.rack_web_set_input_connected(3,1);runtime.rack_web_set_input_channels(3,4);
  for(let channel=0;channel<4;channel++)inputs.fill(channel*.5,(channel*inputCount+3)*128,(channel*inputCount+4)*128);
  runtime.rack_web_process(128,48000);assert.equal(runtime.rack_web_get_output_channels(0),4);
  assert.equal(new Set(Array.from({length:4},(_,channel)=>outputs[channel*128+127].toFixed(4))).size,4);
});

test("official Fundamental VCO2 preserves wavetable assets, morphing, FM, polyphony, lights, and state",()=>{
  const catalog=JSON.parse(fs.readFileSync(new URL("../public/dynamic-plugins/catalog.json",import.meta.url),"utf8")),definition=catalog.find(item=>item.key==="Fundamental/VCO2");assert.ok(definition);assert.equal(definition.localBuild.sourceCommit,"e0ade9a23a9b41124ea3f4ec9aa2cb0b98c2529e");assert.deepEqual([definition.width,definition.params.length,definition.inputs.length,definition.outputs.length,definition.lights,definition.runtime.initialMemory],[105,7,4,1,5,37748736]);assert.deepEqual(definition.runtime.asset,{type:"audio",maxSamples:65536,maxSeconds:0,channels:2});assert.ok([...definition.params.filter(param=>!param.hidden),...definition.inputs,...definition.outputs,...definition.lightWidgets].every(control=>control.position));
  const instantiate=()=>{const runtime=loadDynamicRuntime("Fundamental","VCO2"),inputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_input_buffer(),4*16*128),outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),16*128),lights=new Float32Array(runtime.memory.buffer,runtime.rack_web_light_buffer(),5);for(const param of definition.params)runtime.rack_web_set_param(param.id,param.default);runtime.rack_web_set_output_connected(0,1);return{runtime,inputs,outputs,lights}},render=(unit,sampleRate,blocks=96,channel=0)=>{const samples=[];for(let block=0;block<blocks;block++){unit.runtime.rack_web_process(128,sampleRate);samples.push(...unit.outputs.slice(channel*128,(channel+1)*128))}return samples},measure=(samples,sampleRate)=>{const crossings=samples.slice(1).reduce((count,value,index)=>count+(samples[index]<=0&&value>0),0);return{frequency:crossings*sampleRate/samples.length,min:Math.min(...samples),max:Math.max(...samples),rms:Math.sqrt(samples.reduce((sum,value)=>sum+value*value,0)/samples.length)}},offset=(port,channel)=>(channel*4+port)*128,snapshot=runtime=>{const length=runtime.rack_web_snapshot_state_json();return JSON.parse(new TextDecoder().decode(new Uint8Array(runtime.memory.buffer,runtime.rack_web_snapshot_state_buffer(),length)))};
  for(const sampleRate of [44100,48000]){
    const base=instantiate(),baseStats=measure(render(base,sampleRate),sampleRate);assert.ok(baseStats.min<-4.9&&baseStats.max>4.9&&Math.abs(baseStats.frequency-261.626)<5,`${sampleRate}: default wavetable pitch/range failed`);
    base.runtime.rack_web_set_input_connected(3,1);base.runtime.rack_web_set_input_channels(3,4);for(let channel=0;channel<4;channel++)base.inputs.fill(channel*.25,offset(3,channel),offset(3,channel)+128);const frequencies=Array.from({length:4},(_,channel)=>measure(render(base,sampleRate,128,channel),sampleRate).frequency);assert.equal(base.runtime.rack_web_get_output_channels(0),4);for(let channel=1;channel<4;channel++)assert.ok(Math.abs(frequencies[channel]/frequencies[0]-2**(channel*.25))<.04,`${sampleRate}: polyphonic pitch failed`);
    const morph=instantiate(),asset=new Float32Array(morph.runtime.memory.buffer,morph.runtime.rack_web_asset_buffer(),morph.runtime.rack_web_asset_capacity());for(let index=0;index<64;index++)asset[index]=Math.sin(2*Math.PI*index/64);for(let index=0;index<64;index++)asset[64+index]=index<32?1:-1;morph.runtime.rack_web_commit_asset(128,1,64);morph.runtime.rack_web_set_param(3,0);const sine=measure(render(morph,sampleRate),sampleRate);morph.runtime.rack_web_set_param(3,1);const square=measure(render(morph,sampleRate),sampleRate);assert.ok(square.rms>sine.rms*1.25&&square.max/square.rms<sine.max/sine.rms,`${sampleRate}: wavetable morph failed`);assert.deepEqual(snapshot(morph.runtime),{waveLen:64,filename:"browser://wavetable"});
    const fmFrequency=linear=>{const unit=instantiate();unit.runtime.rack_web_set_input_connected(0,1);unit.runtime.rack_web_set_input_channels(0,1);unit.inputs.fill(.5,offset(0,0),offset(0,0)+128);unit.runtime.rack_web_set_param(4,1);unit.runtime.rack_web_set_param(6,linear);return measure(render(unit,sampleRate,128),sampleRate).frequency};assert.ok(fmFrequency(1)>fmFrequency(0)*1.035,`${sampleRate}: linear and exponential FM collapsed`);
    base.runtime.rack_web_set_param(1,1);base.runtime.rack_web_set_param(6,1);base.runtime.rack_web_process(32,sampleRate);assert.ok(base.lights[3]>.9&&base.lights[4]>.9,`${sampleRate}: switch lights failed`);
  }
  const maximum=instantiate(),asset=new Float32Array(maximum.runtime.memory.buffer,maximum.runtime.rack_web_asset_buffer(),maximum.runtime.rack_web_asset_capacity());for(let index=0;index<asset.length;index++)asset[index]=Math.sin(2*Math.PI*(index%1024)/1024);maximum.runtime.rack_web_commit_asset(asset.length,1,1024);assert.ok(render(maximum,48000,16).every(Number.isFinite));assert.deepEqual(snapshot(maximum.runtime),{waveLen:1024,filename:"browser://wavetable"});
});

test("official Fundamental LFO2 preserves clock/reset, offset/invert, polyphonic FM, and wavetable assets",()=>{
  const catalog=JSON.parse(fs.readFileSync(new URL("../public/dynamic-plugins/catalog.json",import.meta.url),"utf8")),definition=catalog.find(item=>item.key==="Fundamental/LFO2");assert.ok(definition);assert.equal(definition.localBuild.sourceCommit,"e0ade9a23a9b41124ea3f4ec9aa2cb0b98c2529e");assert.deepEqual([definition.width,definition.params.length,definition.inputs.length,definition.outputs.length,definition.lights,definition.runtime.initialMemory],[105,6,4,1,5,4194304]);assert.deepEqual(definition.runtime.asset,{type:"audio",maxSamples:65536,maxSeconds:0,channels:2});assert.ok([...definition.params,...definition.inputs,...definition.outputs,...definition.lightWidgets].every(control=>control.position));
  const instantiate=()=>{const runtime=loadDynamicRuntime("Fundamental","LFO2"),inputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_input_buffer(),4*16*128),outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),16*128),lights=new Float32Array(runtime.memory.buffer,runtime.rack_web_light_buffer(),5);for(const param of definition.params)runtime.rack_web_set_param(param.id,param.default);runtime.rack_web_set_output_connected(0,1);return{runtime,inputs,outputs,lights}},offset=(port,channel)=>(channel*4+port)*128,render=(unit,sampleRate,blocks,channel=0)=>{const samples=[];for(let block=0;block<blocks;block++){unit.runtime.rack_web_process(128,sampleRate);samples.push(...unit.outputs.slice(channel*128,(channel+1)*128))}return samples},measure=(samples,sampleRate,midpoint=5)=>{let minimum=Infinity,maximum=-Infinity,energy=0;const crossings=[];for(const [index,value] of samples.entries()){minimum=Math.min(minimum,value);maximum=Math.max(maximum,value);energy+=value*value;if(index&&samples[index-1]<=midpoint&&value>midpoint)crossings.push(index)}return{minimum,maximum,rms:Math.sqrt(energy/samples.length),frequency:crossings.length>1?(crossings.length-1)*sampleRate/(crossings.at(-1)-crossings[0]):0}},snapshot=runtime=>{const length=runtime.rack_web_snapshot_state_json();return JSON.parse(new TextDecoder().decode(new Uint8Array(runtime.memory.buffer,runtime.rack_web_snapshot_state_buffer(),length)))};
  for(const sampleRate of [44100,48000]){
    const base=instantiate(),baseStats=measure(render(base,sampleRate,Math.ceil(sampleRate*1.5/128)),sampleRate);assert.ok(baseStats.minimum<.01&&baseStats.maximum>9.99&&Math.abs(baseStats.frequency-2)<.01,`${sampleRate}: default LFO failed`);const bipolar=instantiate();bipolar.runtime.rack_web_set_param(0,0);const bipolarStats=measure(render(bipolar,sampleRate,Math.ceil(sampleRate/128)),sampleRate,0);assert.ok(bipolarStats.minimum<-4.99&&bipolarStats.maximum>4.99);const inverted=instantiate();inverted.runtime.rack_web_set_param(1,1);const normalSamples=render(instantiate(),sampleRate,64),invertedSamples=render(inverted,sampleRate,64);assert.ok(normalSamples.every((value,index)=>Math.abs(value+invertedSamples[index]-10)<1e-4));
    const poly=instantiate(),previous=[null,null,null,null],crossings=[[],[],[],[]];poly.runtime.rack_web_set_param(4,1);poly.runtime.rack_web_set_input_connected(0,1);poly.runtime.rack_web_set_input_channels(0,4);for(let channel=0;channel<4;channel++)poly.inputs.fill(channel*.25,offset(0,channel),offset(0,channel)+128);const blocks=Math.ceil(sampleRate*6/128);for(let block=0;block<blocks;block++){poly.runtime.rack_web_process(128,sampleRate);for(let channel=0;channel<4;channel++)for(let frame=0;frame<128;frame++){const value=poly.outputs[channel*128+frame],sample=block*128+frame;if(previous[channel]!==null&&previous[channel]<=5&&value>5)crossings[channel].push(sample);previous[channel]=value}}const frequencies=crossings.map(items=>(items.length-1)*sampleRate/(items.at(-1)-items[0]));assert.equal(poly.runtime.rack_web_get_output_channels(0),4);for(let channel=1;channel<4;channel++)assert.ok(Math.abs(frequencies[channel]/frequencies[0]-2**(channel*.25))<.002,`${sampleRate}: polyphonic FM failed`);
    const reset=instantiate();reset.runtime.rack_web_set_input_connected(1,1);reset.runtime.rack_web_set_input_channels(1,1);render(reset,sampleRate,Math.ceil(sampleRate*.125/128));const beforeReset=reset.outputs[127];reset.inputs[offset(1,0)]=10;reset.runtime.rack_web_process(1,sampleRate);assert.ok(beforeReset>9.8&&Math.abs(reset.outputs[0]-5)<.01,`${sampleRate}: reset failed`);
    const clock=instantiate(),clocked=[];clock.runtime.rack_web_set_input_connected(3,1);clock.runtime.rack_web_set_input_channels(3,1);for(let block=0;block<Math.ceil(sampleRate*1.5/128);block++){clock.inputs.fill(0);for(let frame=0;frame<128;frame++)if((block*128+frame)%Math.round(sampleRate/10)===0)clock.inputs[offset(3,0)+frame]=10;clock.runtime.rack_web_process(128,sampleRate);if(block*128>sampleRate*.5)clocked.push(...clock.outputs.slice(0,128))}assert.ok(Math.abs(measure(clocked,sampleRate).frequency-10)<.02,`${sampleRate}: clock failed`);
    const morph=instantiate(),asset=new Float32Array(morph.runtime.memory.buffer,morph.runtime.rack_web_asset_buffer(),morph.runtime.rack_web_asset_capacity());morph.runtime.rack_web_set_param(0,0);for(let index=0;index<64;index++)asset[index]=Math.sin(2*Math.PI*index/64);for(let index=0;index<64;index++)asset[64+index]=index<32?1:-1;morph.runtime.rack_web_commit_asset(128,1,64);morph.runtime.rack_web_set_param(3,0);const sine=measure(render(morph,sampleRate,Math.ceil(sampleRate/128)),sampleRate,0);morph.runtime.rack_web_set_param(3,1);const square=measure(render(morph,sampleRate,Math.ceil(sampleRate/128)),sampleRate,0);assert.ok(square.rms>sine.rms*1.25);assert.deepEqual(snapshot(morph.runtime),{waveLen:64,filename:"browser://wavetable"});base.runtime.rack_web_set_param(1,1);base.runtime.rack_web_process(32,sampleRate);assert.ok(base.lights[3]>.9&&base.lights[4]>.9);
  }
  const maximum=instantiate(),asset=new Float32Array(maximum.runtime.memory.buffer,maximum.runtime.rack_web_asset_buffer(),maximum.runtime.rack_web_asset_capacity());for(let index=0;index<asset.length;index++)asset[index]=Math.sin(2*Math.PI*(index%1024)/1024);maximum.runtime.rack_web_commit_asset(asset.length,1,1024);assert.ok(render(maximum,48000,16).every(Number.isFinite));assert.deepEqual(snapshot(maximum.runtime),{waveLen:1024,filename:"browser://wavetable"});
});

test("official Expert Sleepers ES-5 packs six CV bytes into signed stereo 24-bit audio",()=>{
  const catalog=JSON.parse(fs.readFileSync(new URL("../public/dynamic-plugins/catalog.json",import.meta.url),"utf8")),definition=catalog.find(item=>item.key==="ExpertSleepers-Encoders/ExpertSleepers-Encoders-ES5");assert.ok(definition);assert.equal(definition.localBuild.sourceCommit,"95496e8a955407889bbab94cf404cf356802bb76");assert.deepEqual([definition.width,definition.params.length,definition.inputs.length,definition.outputs.length,definition.lights,definition.runtime.initialMemory],[45,0,6,2,0,4194304]);assert.deepEqual(definition.inputs.map(({kind,position})=>[kind,position]),Array.from({length:6},(_,id)=>["cv",{x:17,y:45+33*id}]));assert.deepEqual(definition.outputs.map(({kind,position})=>[kind,position]),Array.from({length:2},(_,id)=>["audio",{x:17,y:(9+id)*33}]));
  const instantiate=()=>{const runtime=loadDynamicRuntime("ExpertSleepers-Encoders","ExpertSleepers-Encoders-ES5"),inputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_input_buffer(),6*16*128),outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),2*16*128);for(let input=0;input<6;input++){runtime.rack_web_set_input_connected(input,1);runtime.rack_web_set_input_channels(input,1)}for(let output=0;output<2;output++)runtime.rack_web_set_output_connected(output,1);return{runtime,inputs,outputs}},setBytes=(unit,values)=>{unit.inputs.fill(0);for(const [port,value] of values.entries())unit.inputs.fill(value,port*128,(port+1)*128)},process=(unit,sampleRate)=>{unit.runtime.rack_web_process(128,sampleRate);return[unit.outputs[0],unit.outputs[128]]},loadState=(runtime,state)=>{const bytes=new TextEncoder().encode(JSON.stringify(state)),pointer=runtime.rack_web_state_buffer(bytes.length);new Uint8Array(runtime.memory.buffer,pointer,bytes.length).set(bytes);assert.equal(runtime.rack_web_commit_state_json(bytes.length),1)},snapshot=runtime=>{const length=runtime.rack_web_snapshot_state_json();return JSON.parse(new TextDecoder().decode(new Uint8Array(runtime.memory.buffer,runtime.rack_web_snapshot_state_buffer(),length)))};
  for(const sampleRate of [44100,48000]){const unit=instantiate();assert.deepEqual([unit.runtime.rack_web_param_count(),unit.runtime.rack_web_input_count(),unit.runtime.rack_web_output_count(),unit.runtime.rack_web_light_count()],[0,6,2,0]);setBytes(unit,[127,255,255,128,0,0]);let[left,right]=process(unit,sampleRate);assert.ok(Math.abs(left-10*(0x7fffff/0x800000))<1e-6&&right===-10,`${sampleRate}: signed extremes failed`);setBytes(unit,[255,255,255,1,2,3]);[left,right]=process(unit,sampleRate);assert.ok(Math.abs(left+10/0x800000)<1e-9&&Math.abs(right-10*(0x010203/0x800000))<1e-7);setBytes(unit,[300.9,-4,255.9,12.9,34.7,56.2]);[left,right]=process(unit,sampleRate);assert.ok(Math.abs(left+10*(0x00ff01/0x800000))<1e-7&&Math.abs(right-10*(0x0c2238/0x800000))<1e-7,`${sampleRate}: clamp/truncation failed`);loadState(unit.runtime,{category:2});setBytes(unit,[127,255,255,128,0,1]);[left,right]=process(unit,sampleRate);assert.ok(Math.abs(left-10)<1e-6&&Math.abs(right+10)<2e-6);assert.deepEqual(snapshot(unit.runtime),{category:2});loadState(unit.runtime,{category:1});setBytes(unit,[127,255,128,0,0,0]);assert.deepEqual(process(unit,sampleRate),[10,0]);assert.deepEqual(snapshot(unit.runtime),{category:1});assert.ok(unit.outputs.every(Number.isFinite))}
});

