test("official Expert Sleepers Calibrator preserves its two-point input/output workflows and LEDs",()=>{
  const catalog=JSON.parse(fs.readFileSync(new URL("../public/dynamic-plugins/catalog.json",import.meta.url),"utf8")),definition=catalog.find(item=>item.key==="ExpertSleepers-Encoders/ExpertSleepers-Encoders-Calibrator");assert.ok(definition);assert.equal(definition.localBuild.sourceCommit,"95496e8a955407889bbab94cf404cf356802bb76");assert.deepEqual([definition.width,definition.params.length,definition.inputs.length,definition.outputs.length,definition.lights,definition.runtime.initialMemory],[90,2,2,2,2,4194304]);assert.deepEqual(definition.params.map(({name,button,position})=>[name,button,position]),[["Calibrate input",true,{x:8,y:160,widget:"LEDButton"}],["Calibrate output",true,{x:8,y:190,widget:"LEDButton"}]]);assert.deepEqual(definition.inputs.map(({kind,position})=>[kind,position]),[["cv",{x:5,y:230}],["cv",{x:5,y:300}]]);assert.deepEqual(definition.outputs.map(({kind,position})=>[kind,position]),[["cv",{x:5,y:260}],["cv",{x:5,y:330}]]);assert.deepEqual(definition.lightWidgets.map(({id,position})=>[id,position]),[[0,{x:12.4,y:164.4}],[1,{x:12.4,y:194.4}]]);
  const instantiate=()=>{const runtime=loadDynamicRuntime("ExpertSleepers-Encoders","ExpertSleepers-Encoders-Calibrator"),inputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_input_buffer(),2*16*128),outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),2*16*128),lights=new Float32Array(runtime.memory.buffer,runtime.rack_web_light_buffer(),2);for(let port=0;port<2;port++){runtime.rack_web_set_input_connected(port,1);runtime.rack_web_set_input_channels(port,1);runtime.rack_web_set_output_connected(port,1)}return{runtime,inputs,outputs,lights}},setInput=(unit,port,value)=>unit.inputs.fill(value,port*128,(port+1)*128),render=(unit,frames,sampleRate)=>{while(frames>0){const block=Math.min(128,frames);unit.runtime.rack_web_process(block,sampleRate);frames-=block}return[unit.outputs[0],unit.outputs[128]]},loadState=(runtime,state)=>{const bytes=new TextEncoder().encode(JSON.stringify(state)),pointer=runtime.rack_web_state_buffer(bytes.length);new Uint8Array(runtime.memory.buffer,pointer,bytes.length).set(bytes);assert.equal(runtime.rack_web_commit_state_json(bytes.length),1)},snapshot=runtime=>{const length=runtime.rack_web_snapshot_state_json();return JSON.parse(new TextDecoder().decode(new Uint8Array(runtime.memory.buffer,runtime.rack_web_snapshot_state_buffer(),length)))},near=(actual,expected,tolerance=1e-5)=>assert.ok(Math.abs(actual-expected)<tolerance,`${actual} != ${expected}`);
  for(const sampleRate of [44100,48000]){
    const mapped=instantiate();assert.deepEqual([mapped.runtime.rack_web_param_count(),mapped.runtime.rack_web_input_count(),mapped.runtime.rack_web_output_count(),mapped.runtime.rack_web_light_count()],[2,2,2,2]);setInput(mapped,0,1.5);setInput(mapped,1,1.5);let[inputOutput,outputOutput]=render(mapped,1,sampleRate);near(inputOutput,1.5);near(outputOutput,1.5);loadState(mapped.runtime,{in0V:.2,in3V:3.2,out0V:.1,out3V:3.1});setInput(mapped,0,1.7);setInput(mapped,1,1.5);[inputOutput,outputOutput]=render(mapped,1,sampleRate);near(inputOutput,1.5);near(outputOutput,1.6);const mappedState=snapshot(mapped.runtime);near(mappedState.in0V,.2);near(mappedState.in3V,3.2);near(mappedState.out0V,.1);near(mappedState.out3V,3.1);
    const inputCalibration=instantiate();inputCalibration.runtime.rack_web_set_param(0,1);render(inputCalibration,1,sampleRate);inputCalibration.runtime.rack_web_set_param(0,0);render(inputCalibration,Math.ceil(sampleRate*.11),sampleRate);assert.ok(inputCalibration.lights[0]<.1,`${sampleRate}: input prompt did not flash`);inputCalibration.runtime.rack_web_set_param(0,1);render(inputCalibration,1,sampleRate);setInput(inputCalibration,0,.25);render(inputCalibration,20000,sampleRate);inputCalibration.runtime.rack_web_set_param(0,0);render(inputCalibration,1,sampleRate);inputCalibration.runtime.rack_web_set_param(0,1);render(inputCalibration,1,sampleRate);setInput(inputCalibration,0,3.25);render(inputCalibration,20000,sampleRate);const inputState=snapshot(inputCalibration.runtime);near(inputState.in0V,.25);near(inputState.in3V,3.25);setInput(inputCalibration,0,1.75);near(render(inputCalibration,1,sampleRate)[0],1.5);
    const outputCalibration=instantiate();outputCalibration.runtime.rack_web_set_param(1,1);render(outputCalibration,1,sampleRate);outputCalibration.runtime.rack_web_set_param(1,0);render(outputCalibration,1,sampleRate);outputCalibration.runtime.rack_web_set_param(1,1);render(outputCalibration,1,sampleRate);setInput(outputCalibration,0,.15);render(outputCalibration,20000,sampleRate);setInput(outputCalibration,0,3.15);render(outputCalibration,Math.floor(sampleRate/2)+2,sampleRate);render(outputCalibration,20000,sampleRate);const outputState=snapshot(outputCalibration.runtime);near(outputState.out0V,.15);near(outputState.out3V,3.15);setInput(outputCalibration,1,1.65);near(render(outputCalibration,1,sampleRate)[1],1.5);assert.ok(outputCalibration.outputs.every(Number.isFinite));
  }
});

