    const create=()=>loadDynamicRuntime("Edge","K_Rush"),snapshot=runtime=>{const length=runtime.rack_web_snapshot_state_json();return JSON.parse(new TextDecoder().decode(new Uint8Array(runtime.memory.buffer,runtime.rack_web_snapshot_state_buffer(),length)))},commit=(runtime,state)=>{const encoded=new TextEncoder().encode(JSON.stringify(state)),pointer=runtime.rack_web_state_buffer(encoded.length);new Uint8Array(runtime.memory.buffer,pointer,encoded.length).set(encoded);assert.equal(runtime.rack_web_commit_state_json(encoded.length),1)},difference=(left,right)=>left.reduce((sum,value,index)=>sum+Math.abs(value-right[index]),0);
    const render=({mix=1,gain=1,wave=0,algorithm=1,typeCv=0,gainCv=0,feedbackCv=0,feedback=0,channels=1}={})=>{const runtime=create(),inputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_input_buffer(),5*16*128),outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),2*16*128),samples=[];assert.deepEqual([runtime.rack_web_param_count(),runtime.rack_web_input_count(),runtime.rack_web_output_count(),runtime.rack_web_light_count(),runtime.memory.buffer.byteLength],[7,5,2,0,16777216]);for(const [id,value] of [[0,1],[1,mix],[2,.7],[3,gain],[4,wave],[5,.5],[6,.3]])runtime.rack_web_set_param(id,value);commit(runtime,{first_alg:algorithm});for(const id of [0,1,2,3,4]){runtime.rack_web_set_input_connected(id,1);runtime.rack_web_set_input_channels(id,id===2?channels:1)}for(const id of [0,1])runtime.rack_web_set_output_connected(id,1);inputs.fill(typeCv,0,128);inputs.fill(gainCv,128,256);inputs.fill(feedbackCv,3*128,4*128);inputs.fill(feedback,4*128,5*128);for(let block=0;block<12;block++){for(let channel=0;channel<channels;channel++)for(let frame=0;frame<128;frame++)inputs[(channel*5+2)*128+frame]=Math.sin((block*128+frame)*.071+channel*.2)*4/(channel+1);runtime.rack_web_process(128,sampleRate);samples.push(...outputs.slice(0,128))}return{runtime,samples,state:snapshot(runtime)}};
    const dry=render({mix:0}),wet=render({gain:4,wave:7}),differentWave=render({gain:4,wave:12}),modulated=render({gain:4,wave:7,typeCv:1.75,gainCv:4,feedbackCv:10,feedback:3}),second=render({gain:4,wave:15,algorithm:0,typeCv:-10,feedbackCv:10,feedback:-3}),poly=render({mix:0,channels:4});
