test("official HetrickCV Boolean3 preserves two and three input truth tables, hysteresis, polyphony, and lights",()=>{
  const catalog=JSON.parse(fs.readFileSync(new URL("../public/dynamic-plugins/catalog.json",import.meta.url),"utf8")),definition=catalog.find(item=>item.key==="HetrickCV/Boolean3");assert.ok(definition);assert.equal(definition.localBuild.sourceCommit,"ad0b04c7d7aa0087dbffb9fae32ac98a4b5621fe");assert.deepEqual([definition.width,definition.params.length,definition.inputs.length,definition.outputs.length,definition.lights,definition.runtime.initialMemory],[90,0,3,6,9,4194304]);
  assert.deepEqual(definition.inputs.map(({id,name,kind,position})=>[id,name,kind,position]),[[0,"A","cv",{x:10,y:105}],[1,"B","cv",{x:10,y:195}],[2,"C","cv",{x:10,y:285}]]);
  assert.deepEqual(definition.outputs.map(({id,name,kind,position})=>[id,name,kind,position]),[[0,"OR","cv",{x:45,y:60}],[1,"AND","cv",{x:45,y:105}],[2,"XOR","cv",{x:45,y:150}],[3,"NOR","cv",{x:45,y:195}],[4,"NAND","cv",{x:45,y:240}],[5,"XNOR","cv",{x:45,y:285}]]);
  assert.deepEqual(definition.lightWidgets.map(({id,position})=>[id,position]),[[6,{x:18,y:92}],[7,{x:18,y:182}],[8,{x:18,y:272}],[0,{x:74,y:68}],[1,{x:74,y:113}],[2,{x:74,y:158}],[3,{x:74,y:203}],[4,{x:74,y:248}],[5,{x:74,y:293}]]);
  const create=()=>{const runtime=loadDynamicRuntime("HetrickCV","Boolean3");for(let id=0;id<3;id++){runtime.rack_web_set_input_connected(id,1);runtime.rack_web_set_input_channels(id,1)}for(let id=0;id<6;id++)runtime.rack_web_set_output_connected(id,1);return runtime},truth=(a,b,c,three=true)=>{const runtime=create(),inputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_input_buffer(),3*16*128),outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),6*16*128);if(!three)runtime.rack_web_set_input_connected(2,0);inputs[0]=a?10:0;inputs[128]=b?10:0;inputs[256]=c?10:0;runtime.rack_web_process(1,48000);return{values:Array.from({length:6},(_,id)=>outputs[id*128]),lights:Array.from(new Float32Array(runtime.memory.buffer,runtime.rack_web_light_buffer(),9))}};
  for(const a of [false,true])for(const b of [false,true]){const result=truth(a,b,false,false),or=a||b,and=a&&b,xor=a!==b;assert.deepEqual(result.values,[or?10:0,and?10:0,xor?10:0,or?0:10,and?0:10,xor?0:10])}
  for(const a of [false,true])for(const b of [false,true])for(const c of [false,true]){const result=truth(a,b,c),or=a||b||c,and=a&&b&&c,xor=Number(a)+Number(b)+Number(c)===1;assert.deepEqual(result.values,[or?10:0,and?10:0,xor?10:0,or?0:10,and?0:10,xor?0:10]);assert.deepEqual(result.lights,[...result.values,a?10:0,b?10:0,c?10:0])}
  const hysteresis=create(),hysteresisInputs=new Float32Array(hysteresis.memory.buffer,hysteresis.rack_web_input_buffer(),3*16*128),hysteresisOutputs=new Float32Array(hysteresis.memory.buffer,hysteresis.rack_web_output_buffer(),6*16*128);hysteresis.rack_web_set_input_connected(2,0);for(const [value,expected] of [[1,0],[1.01,10],[.99,10],[.97,0]]){hysteresisInputs[0]=value;hysteresis.rack_web_process(1,44100);assert.equal(hysteresisOutputs[0],expected)}
  const poly=loadDynamicRuntime("HetrickCV","Boolean3"),polyInputs=new Float32Array(poly.memory.buffer,poly.rack_web_input_buffer(),3*16*128),polyOutputs=new Float32Array(poly.memory.buffer,poly.rack_web_output_buffer(),6*16*128);poly.rack_web_set_polyphony(4);for(const id of [0,1]){poly.rack_web_set_input_connected(id,1);poly.rack_web_set_input_channels(id,4)}poly.rack_web_set_input_connected(2,0);for(const id of [0,1,2,3,4,5])poly.rack_web_set_output_connected(id,1);for(let channel=0;channel<4;channel++){polyInputs[(channel*3)*128]=channel&1?10:0;polyInputs[(channel*3+1)*128]=channel&2?10:0}poly.rack_web_process(1,48000);assert.ok(Array.from({length:6},(_,id)=>poly.rack_web_get_output_channels(id)).every(channels=>channels===4));assert.deepEqual(Array.from({length:4},(_,channel)=>Array.from({length:6},(_,id)=>polyOutputs[(channel*6+id)*128])),[[0,0,0,10,10,10],[10,0,10,0,10,0],[10,0,10,0,10,0],[10,10,0,0,0,10]]);
});

