  const catalog=JSON.parse(fs.readFileSync(new URL("../public/dynamic-plugins/catalog.json",import.meta.url),"utf8")),commit="3a9441f594d6a7cc8b6f11c19ff81d95ff8977ad",recorderDefinition=catalog.find(item=>item.key==="Ahornberg/TapeRecorder"),inspectorDefinition=catalog.find(item=>item.key==="Ahornberg/TapeInspector");
