  for(const param of recorderDefinition.params)for(const value of [param.min,(param.min+param.max)/2,param.max]){recorder.rack_web_set_param(param.id,value);recorder.rack_web_process(1,48000);assert.ok(outputs.every(Number.isFinite),`${param.name} produced a non-finite value at ${value}`)}for(const param of recorderDefinition.params)recorder.rack_web_set_param(param.id,param.default);
