test("Autinn Trace preserves NanoSVG paths as polyphonic X/Y scope voltages",()=>{
  const catalog=JSON.parse(fs.readFileSync(new URL("../public/dynamic-plugins/catalog.json",import.meta.url),"utf8")),definition=catalog.find(item=>item.key==="Autinn/Trace");assert.ok(definition);assert.equal(definition.localBuild.sourceCommit,"eff448f818f7ca94c6a893b69a907fcf45f0a639");assert.equal(definition.runtime.strategy,"direct-rack-source-adapter");assert.deepEqual([definition.width,definition.params.length,definition.inputs.length,definition.outputs.length,definition.lights],[150,3,3,2,0]);assert.deepEqual(definition.params.map(param=>param.name),["Frequency","Scale","Rotate"]);assert.deepEqual(definition.outputs.map(output=>output.name),["X Axis","Y Axis"]);assert.ok([...definition.params,...definition.inputs,...definition.outputs].every(control=>control.position));
  const svg='<svg width="100" height="100" xmlns="http://www.w3.org/2000/svg"><path d="M0 0 L20 0 L20 20 Z"/><path d="M60 60 C80 60 80 80 60 80 Z"/></svg>',encoded=new TextEncoder().encode(JSON.stringify({svg}));
  for(const sampleRate of [44100,48000]){const runtime=loadDynamicRuntime("Autinn","Trace"),outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),2*16*128);for(const param of definition.params)runtime.rack_web_set_param(param.id,param.default);runtime.rack_web_set_output_connected(0,1);runtime.rack_web_set_output_connected(1,1);runtime.rack_web_process(128,sampleRate);assert.deepEqual([runtime.rack_web_get_output_channels(0),runtime.rack_web_get_output_channels(1)],[1,1]);assert.ok(outputs.every(Number.isFinite));assert.ok(Math.max(...outputs)-Math.min(...outputs)>.1);
    const pointer=runtime.rack_web_state_buffer(encoded.length);new Uint8Array(runtime.memory.buffer,pointer,encoded.length).set(encoded);assert.equal(runtime.rack_web_commit_state_json(encoded.length),1);const ranges=Array.from({length:4},()=>[Infinity,-Infinity]);for(let block=0;block<32;block++){runtime.rack_web_process(128,sampleRate);for(let lane=0;lane<4;lane++)for(const value of outputs.slice(lane*128,(lane+1)*128)){ranges[lane][0]=Math.min(ranges[lane][0],value);ranges[lane][1]=Math.max(ranges[lane][1],value)}}assert.deepEqual([runtime.rack_web_get_output_channels(0),runtime.rack_web_get_output_channels(1)],[2,2]);assert.ok(outputs.every(Number.isFinite));assert.ok(ranges.every(([minimum,maximum])=>maximum-minimum>.01));
    const length=runtime.rack_web_snapshot_state_json(),state=JSON.parse(new TextDecoder().decode(new Uint8Array(runtime.memory.buffer,runtime.rack_web_snapshot_state_buffer(),length)));assert.equal((state.svg.match(/<path /g)??[]).length,2);assert.match(state.svg,/C/);const restored=loadDynamicRuntime("Autinn","Trace"),restoredBytes=new TextEncoder().encode(JSON.stringify(state)),restoredPointer=restored.rack_web_state_buffer(restoredBytes.length);new Uint8Array(restored.memory.buffer,restoredPointer,restoredBytes.length).set(restoredBytes);assert.equal(restored.rack_web_commit_state_json(restoredBytes.length),1);restored.rack_web_process(1,sampleRate);assert.equal(restored.rack_web_get_output_channels(0),2)}
});

