    clock();assert.equal(outputs[3*128],10);approximately(outputs[0],10/15);approximately(outputs[11*128],10/255-5);for(let pulse=1;pulse<4;pulse++)clock();approximately(outputs[0],10);setInput(4,10);process();assert.deepEqual(Array.from({length:8},(_,bit)=>outputs[(3+bit)*128]),Array(8).fill(0));approximately(outputs[11*128],-5);setInput(4,0);process();runtime.rack_web_set_state(0,1);runtime.rack_web_set_state(8,1);process();assert.equal(outputs[3*128],10);runtime.rack_web_set_state(8,2);clock();assert.equal(outputs[4*128],10);setInput(3,0);for(let block=0;block<2;block++)process(128);assert.equal(outputs[4*128],0);const length=runtime.rack_web_snapshot_state_json(),snapshot=JSON.parse(new TextDecoder().decode(new Uint8Array(runtime.memory.buffer,runtime.rack_web_snapshot_state_buffer(),length)));assert.deepEqual(snapshot.values.slice(0,2),[true,true]);assert.equal(snapshot.outputType,2);assert.ok(outputs.every(Number.isFinite));assert.ok(lights.every(Number.isFinite));
