    runtime.rack_web_set_param(0,6);inputs[128]=.2;runtime.rack_web_process(1,sampleRate);approximately(read(0,1),1/3);runtime.rack_web_set_param(0,0);inputs[128]=0;runtime.rack_web_set_input_channels(1,2);inputs[4*128]=.5;runtime.rack_web_process(1,sampleRate);assert.deepEqual([runtime.rack_web_get_output_channels(0),runtime.rack_web_get_output_channels(1)],[4,2]);approximately(read(1,1),7/12);approximately(read(2,0),.5);approximately(read(3,0),7/12);
