test("Voxglitch ByteBeat, Digital Programmer, Drum Randomizer, and Groove Box Expander preserve their core contracts",()=>{
  const bytebeat=loadDynamicRuntime("voxglitch","bytebeat"),bytebeatOutput=new Float32Array(bytebeat.memory.buffer,bytebeat.rack_web_output_buffer(),2*16*128);bytebeat.rack_web_set_output_connected(0,1);let bytebeatPeak=0;for(let block=0;block<8;block++){bytebeat.rack_web_process(128,48000);for(const value of bytebeatOutput.slice(0,128)){assert.ok(Number.isFinite(value));bytebeatPeak=Math.max(bytebeatPeak,Math.abs(value))}}assert.ok(bytebeatPeak>=4.9);
  const programmer=loadDynamicRuntime("voxglitch","digitalprogrammer"),programmerInputs=new Float32Array(programmer.memory.buffer,programmer.rack_web_input_buffer(),5*16*128),programmerOutputs=new Float32Array(programmer.memory.buffer,programmer.rack_web_output_buffer(),17*16*128);programmer.rack_web_set_input_connected(4,1);programmer.rack_web_set_input_channels(4,4);for(let output=0;output<17;output++)programmer.rack_web_set_output_connected(output,1);for(let channel=0;channel<4;channel++)programmerInputs[(channel*5+4)*128]=channel+1;programmer.rack_web_process(1,48000);assert.equal(programmer.rack_web_get_output_channels(16),16);assert.deepEqual(Array.from({length:4},(_,channel)=>programmerOutputs[(channel*17+16)*128]),[1,2,3,4]);
  const randomizer=loadDynamicRuntime("voxglitch","drumrandomizer"),randomizerInputs=new Float32Array(randomizer.memory.buffer,randomizer.rack_web_input_buffer(),3*16*128),randomizerOutputs=new Float32Array(randomizer.memory.buffer,randomizer.rack_web_output_buffer(),16*128);for(const input of [0,1,2]){randomizer.rack_web_set_input_connected(input,1);randomizer.rack_web_set_input_channels(input,input===0?16:1)}randomizer.rack_web_set_output_connected(0,1);randomizer.rack_web_set_param(2,1);for(let channel=0;channel<16;channel++)randomizerInputs[(channel*3)*128]=channel+1;randomizerInputs[128]=10;randomizer.rack_web_process(1,48000);assert.equal(randomizer.rack_web_get_output_channels(0),16);assert.deepEqual(Array.from({length:16},(_,channel)=>randomizerOutputs[channel*128]),Array.from({length:16},(_,channel)=>channel+1));
  const expander=loadDynamicRuntime("voxglitch","GrooveBoxExpander"),expanderLights=new Float32Array(expander.memory.buffer,expander.rack_web_light_buffer(),25);assert.equal(expander.rack_web_message_capacity(),16384);expander.rack_web_set_message_neighbor(1,0,1);expander.rack_web_process(1,48000);assert.equal(expanderLights[24],1);expander.rack_web_set_message_neighbor(1,0,0);expander.rack_web_process(1,48000);assert.equal(expanderLights[24],0);
});

