    const sends=loadDynamicRuntime("QuantalAudio","DaisyChannelSends2"),sendOutputs=new Float32Array(sends.memory.buffer,sends.rack_web_output_buffer(),2*16*128);sends.rack_web_set_param(0,0);sends.rack_web_set_message_neighbor(0,0,1);sends.rack_web_set_output_connected(0,1);sends.rack_web_set_output_connected(1,1);const sendsMessage=sends.rack_web_message_buffer(0,0,1);writeStereo(sends,sendsMessage,264,[1,2],[3,4]);writeStereo(sends,sendsMessage,396,[5,6],[7,8]);sends.rack_web_process(1,sampleRate);assert.deepEqual([sendOutputs[0],sendOutputs[128],sendOutputs[256],sendOutputs[384]],[1,3,2,4]);sends.rack_web_set_param(0,1);sends.rack_web_process(1,sampleRate);sends.rack_web_set_param(0,0);sends.rack_web_process(1,sampleRate);assert.deepEqual([sendOutputs[0],sendOutputs[128],sendOutputs[256],sendOutputs[384]],[5,7,6,8]);assert.equal(snapshot(sends).group,2);
