test("DrumKit OpenHiHat embeds every sample and preserves its dual choke envelopes",()=>{
  const catalog=JSON.parse(fs.readFileSync(new URL("../public/dynamic-plugins/catalog.json",import.meta.url),"utf8")),definition=catalog.find(item=>item.key==="DrumKit/OpenHiHat");assert.ok(definition);assert.equal(definition.localBuild.sourceCommit,"e04dd795ea8d9f08e82a0ca1457fcb9ad59c00ed");assert.deepEqual([definition.width,definition.params.length,definition.inputs.length,definition.outputs.length,definition.lights],[135,50,84,16,0]);assert.equal(definition.runtime.initialMemory,20*1024*1024);assert.deepEqual([0,1,16,17,32,33].map(id=>[definition.params[id].name,definition.params[id].hidden??false]),[["Sample 1",false],["Sample 2",false],["Playback Speed 1",false],["Playback Speed 2",false],["Choke Time 1",false],["Choke Time 2",false]]);assert.deepEqual([definition.params[0].max,definition.params[1].max],[13,13]);assert.deepEqual([0,1,16,17,32,33,48,49,64,65].map(id=>[definition.inputs[id].name,definition.inputs[id].kind,definition.inputs[id].hidden??false]),[["Sample 1 CV","cv",false],["Sample 2 CV","cv",false],["Trigger 1","gate",false],["Trigger 2","gate",false],["Tune 1 CV","cv",false],["Tune 2 CV","cv",false],["Choke Time 1 CV","cv",false],["Choke Time 2 CV","cv",false],["Choke 1","gate",false],["Choke 2","gate",false]]);assert.deepEqual(definition.outputs.slice(0,2).map(({name,kind,hidden=false})=>[name,kind,hidden]),[["Audio 1","audio",false],["Audio 2","audio",false]]);assert.ok([...definition.params,...definition.inputs,...definition.outputs].filter(control=>!control.hidden).every(control=>control.position));
  for(const sampleRate of [44100,48000]){
    const runtime=loadDynamicRuntime("DrumKit","OpenHiHat"),inputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_input_buffer(),84*16*128),outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),16*16*128),setInput=(port,value)=>inputs.fill(value,port*128,(port+1)*128),voice1=[],voice2=[];for(const param of definition.params)runtime.rack_web_set_param(param.id,param.default);runtime.rack_web_set_param(0,9);runtime.rack_web_set_param(1,9);runtime.rack_web_set_param(16,1);runtime.rack_web_set_param(17,1);runtime.rack_web_set_param(32,.05);runtime.rack_web_set_param(33,.5);for(const port of [0,1,16,17,32,33,48,49,64,65]){runtime.rack_web_set_input_connected(port,1);runtime.rack_web_set_input_channels(port,1)}for(const output of [0,1])runtime.rack_web_set_output_connected(output,1);setInput(16,10);setInput(17,10);runtime.rack_web_process(1,sampleRate);setInput(16,0);setInput(17,0);for(let block=0;block<Math.ceil(sampleRate*.05/128);block++)runtime.rack_web_process(128,sampleRate);setInput(64,10);setInput(65,10);runtime.rack_web_process(1,sampleRate);setInput(64,0);setInput(65,0);for(let block=0;block<Math.ceil(sampleRate*.6/128);block++){runtime.rack_web_process(128,sampleRate);voice1.push(...outputs.slice(0,128));voice2.push(...outputs.slice(128,256))}const peak=values=>values.reduce((maximum,value)=>Math.max(maximum,Math.abs(value)),0),active=values=>values.reduce((count,value)=>count+(Math.abs(value)>1e-5),0),fastTail=voice1.slice(Math.ceil(sampleRate*.1)),slowTail=voice2.slice(Math.ceil(sampleRate*.1));assert.ok([...voice1,...voice2].every(Number.isFinite));assert.ok(peak(voice1)>1&&peak(voice2)>1,`${sampleRate}: open hats stayed silent`);assert.ok(active(voice2)>active(voice1)*3,`${sampleRate}: choke times were not independent`);assert.ok(peak(fastTail)<1e-5,`${sampleRate}: fast choke did not close`);assert.ok(peak(slowTail)>.1,`${sampleRate}: slow choke closed too soon`);
  }
});

