  for(const sampleRate of [44100,48000]){
    const runtime=loadDynamicRuntime("FrankBuss","Formula"),inputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_input_buffer(),4*16*128),outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),16*128),lights=new Float32Array(runtime.memory.buffer,runtime.rack_web_light_buffer(),6),setPort=(port,values)=>{runtime.rack_web_set_input_connected(port,1);runtime.rack_web_set_input_channels(port,values.length);for(const [channel,value] of values.entries())inputs[(channel*4+port)*128]=value},read=()=>Array.from({length:4},(_,channel)=>outputs[channel*128]),approximately=(actual,expected)=>actual.forEach((value,index)=>assert.ok(Math.abs(value-expected[index])<1e-5,`${sampleRate}: ${value} != ${expected[index]}`)),pulse=id=>{runtime.rack_web_set_param(id,1);runtime.rack_web_process(1,sampleRate);runtime.rack_web_set_param(id,0);runtime.rack_web_process(1,sampleRate)};for(const param of definition.params)runtime.rack_web_set_param(param.id,param.default);loadState(runtime,{text:"max(x,y) + min(z,w) + k + b",freq:"",clamp:true,button:0});setPort(0,[1,2,3,4]);setPort(1,[4,3,2,1]);setPort(2,[-1,1,2,8]);setPort(3,[0,0,3,6]);runtime.rack_web_set_output_connected(0,1);runtime.rack_web_set_param(3,.25);runtime.rack_web_process(1,sampleRate);assert.equal(runtime.rack_web_get_output_channels(0),4);approximately(read(),[3.25,3.25,5,5]);pulse(5);approximately(read(),[2.25,2.25,4.25,5]);pulse(4);approximately(read(),[2.25,2.25,4.25,9.25]);pulse(7);approximately(read(),[4.25,4.25,6.25,11.25]);assert.ok(outputs.every(Number.isFinite)&&lights.every(Number.isFinite));const state=snapshot(runtime);assert.deepEqual(state,{text:"max(x,y) + min(z,w) + k + b",freq:"",clamp:false,button:1});const restored=loadDynamicRuntime("FrankBuss","Formula");loadState(restored,state);const restoredInputs=new Float32Array(restored.memory.buffer,restored.rack_web_input_buffer(),4*16*128),restoredOutputs=new Float32Array(restored.memory.buffer,restored.rack_web_output_buffer(),16*128);for(const [port,values] of [[0,[1,2,3,4]],[1,[4,3,2,1]],[2,[-1,1,2,8]],[3,[0,0,3,6]]]){restored.rack_web_set_input_connected(port,1);restored.rack_web_set_input_channels(port,values.length);for(const [channel,value] of values.entries())restoredInputs[(channel*4+port)*128]=value}restored.rack_web_set_param(3,.25);restored.rack_web_set_output_connected(0,1);restored.rack_web_process(1,sampleRate);approximately(Array.from({length:4},(_,channel)=>restoredOutputs[channel*128]),[4.25,4.25,6.25,11.25]);
    const oscillator=loadDynamicRuntime("FrankBuss","Formula"),oscillatorOutputs=new Float32Array(oscillator.memory.buffer,oscillator.rack_web_output_buffer(),16*128),samples=[];for(const param of definition.params)oscillator.rack_web_set_param(param.id,param.default);loadState(oscillator,{text:"sin(p * pi * 2) * 5",freq:"1000",clamp:true,button:0});oscillator.rack_web_set_output_connected(0,1);for(let block=0;block<4;block++){oscillator.rack_web_process(128,sampleRate);samples.push(...oscillatorOutputs.slice(0,128))}const rises=samples.slice(1).reduce((count,value,index)=>count+(samples[index]<=0&&value>0),0),minimum=Math.min(...samples),maximum=Math.max(...samples);assert.ok(minimum<-4.9&&maximum>4.9,`${sampleRate}: oscillator range ${minimum}..${maximum}`);assert.ok(rises>=10&&rises<=13,`${sampleRate}: oscillator cycles ${rises}`);assert.ok(samples.every(Number.isFinite));
  }
