  oscillator.runtime.rack_web_set_param(3,1);oscillator.process(4);preview=oscillator.visual();assert.equal(preview[1],1);let shapeDelta=0;for(let frame=0;frame<128;frame++)shapeDelta=Math.max(shapeDelta,Math.abs(oscillator.outputs[frame]-oscillator.outputs[128+frame]));assert.ok(shapeDelta>1);oscillator.runtime.rack_web_set_state(0,1);oscillator.runtime.rack_web_set_state(1,1);oscillator.runtime.rack_web_set_state(2,0);oscillator.runtime.rack_web_set_state(3,0);assert.deepEqual([oscillator.snapshot().shapeEntryAsymmetry,oscillator.snapshot().shapeEntryAsymmetryOnRight,oscillator.snapshot().analogCharacterEnabled,oscillator.snapshot().previewTracerEnabled],[true,true,false,false]);assert.deepEqual(oscillator.visual().slice(3,6),[1,1,0]);
