  const frames=8192,channels=2,asset=new Float32Array(runtime.memory.buffer,runtime.rack_web_asset_buffer(),frames*channels);for(let frame=0;frame<frames;frame++){asset[frame*2]=Math.sin(frame*.031);asset[frame*2+1]=Math.cos(frame*.047)}runtime.rack_web_commit_asset(frames,channels,48000);let leftPeak=0,rightPeak=0;for(let block=0;block<40;block++){runtime.rack_web_process(128,48000);leftPeak=Math.max(leftPeak,...outputs.slice(0,128).map(Math.abs));rightPeak=Math.max(rightPeak,...outputs.slice(2*128,3*128).map(Math.abs))}assert.ok(leftPeak>4&&rightPeak>4,`expected stereo sample output, received ${leftPeak}, ${rightPeak}`);const loaded=visual();assert.deepEqual(loaded.slice(2,6),[frames,1,1,1]);assert.ok(Number.isFinite(loaded[0])&&loaded[1]>0);assert.ok(Math.max(...lights.slice(7,69))>.5);
