test("Leviathan TD.Scope consumes Temporal Deck's original stereo expander protocol and preserves display state",()=>{
  const catalog=JSON.parse(fs.readFileSync(new URL("../public/dynamic-plugins/catalog.json",import.meta.url),"utf8")),
    deckDefinition=catalog.find(item=>item.key==="Leviathan/TemporalDeck"),
    scopeDefinition=catalog.find(item=>item.key==="Leviathan/TDScope");
  assert.ok(deckDefinition&&scopeDefinition);
  assert.equal(scopeDefinition.localBuild.sourceCommit,"329ced997934968efba04077b5922fd2442baf0d");
  assert.deepEqual([scopeDefinition.width,scopeDefinition.params.length,scopeDefinition.inputs.length,scopeDefinition.outputs.length,scopeDefinition.lights,scopeDefinition.runtime.initialMemory],[120,0,0,0,2,4*1024*1024]);
  assert.deepEqual(scopeDefinition.runtime.expander,{transport:"message-buffer",direction:"both",capacity:32768,models:[{key:"Leviathan/TemporalDeck",symbol:"modelTemporalDeck",index:0}]});
  assert.deepEqual(scopeDefinition.runtime.visuals,[{kind:"td-scope",offset:0,x:3.291,y:27.728,width:113.843,height:327.666}]);
  assert.deepEqual(scopeDefinition.stateKeys.slice(0,6).map(({key,default:initial,contextOnly})=>[key,initial,contextOnly]),[
    ["scopeDisplayRangeMode",3,true],["scopeVerticalInverted",0,true],["scopeChannelMode",0,true],
    ["scopeColorScheme",0,true],["scopeColorSchemeVersion",2,false],["scopeColorBrightness",.5,true],
  ]);
  const deck=loadDynamicRuntime("Leviathan","TemporalDeck"),scope=loadDynamicRuntime("Leviathan","TDScope"),capacity=32768;
  assert.deepEqual([scope.rack_web_param_count(),scope.rack_web_input_count(),scope.rack_web_output_count(),scope.rack_web_light_count(),scope.rack_web_visual_count(),scope.rack_web_message_capacity()],[0,0,0,2,1032,capacity]);
  deck.rack_web_set_message_neighbor(1,0,1);scope.rack_web_set_message_neighbor(0,0,1);
  const frames=8192,asset=new Float32Array(deck.memory.buffer,deck.rack_web_asset_buffer(),frames*2);
  for(let frame=0;frame<frames;frame++){asset[frame*2]=Math.sin(frame*.031);asset[frame*2+1]=Math.cos(frame*.047)}
  deck.rack_web_commit_asset(frames,2,48000);
  const transferDeckToScope=()=>{
    if(!deck.rack_web_message_flip_requested(1,1))return false;
    new Uint8Array(scope.memory.buffer,scope.rack_web_message_buffer(0,0,0),capacity).set(new Uint8Array(deck.memory.buffer,deck.rack_web_message_buffer(1,1,0),capacity));
    scope.rack_web_finish_message_flip(0,0);deck.rack_web_finish_message_flip(1,1);return true;
  };
  const transferScopeToDeck=()=>{
    if(!scope.rack_web_message_flip_requested(0,1))return false;
    new Uint8Array(deck.memory.buffer,deck.rack_web_message_buffer(1,0,0),capacity).set(new Uint8Array(scope.memory.buffer,scope.rack_web_message_buffer(0,1,0),capacity));
    deck.rack_web_finish_message_flip(1,0);scope.rack_web_finish_message_flip(0,1);return true;
  };
  let published=false;
  for(let block=0;block<16;block++){deck.rack_web_process(128,48000);published=transferDeckToScope()||published;scope.rack_web_process(128,48000);transferScopeToDeck()}
  assert.equal(published,true);
  const lights=new Float32Array(scope.memory.buffer,scope.rack_web_light_buffer(),2),visual=()=>Array.from(new Float32Array(scope.memory.buffer,scope.rack_web_visual_buffer(),scope.rack_web_visual_count()));
  const mono=visual();assert.deepEqual(mono.slice(0,2),[1,1]);assert.deepEqual(mono.slice(6,8),[256,0]);assert.ok(mono.slice(8).some(value=>Math.abs(value)>.01));assert.deepEqual(Array.from(lights),[1,1]);
  scope.rack_web_set_state(2,1);scope.rack_web_set_state(3,4);scope.rack_web_set_state(5,.8);
  for(let block=0;block<20;block++){scope.rack_web_process(128,48000);transferScopeToDeck();deck.rack_web_process(128,48000);transferDeckToScope()}
  scope.rack_web_process(1,48000);
  const stereo=visual();assert.equal(stereo[7],1);assert.ok(stereo.slice(10).filter((_,index)=>index%4>=2).some(value=>Math.abs(value)>.01));
  const length=scope.rack_web_snapshot_state_json(),state=JSON.parse(new TextDecoder().decode(new Uint8Array(scope.memory.buffer,scope.rack_web_snapshot_state_buffer(),length)));
  assert.deepEqual([state.scopeChannelMode,state.scopeColorScheme],[1,4]);assert.ok(Math.abs(state.scopeColorBrightness-.8)<1e-6);
  scope.rack_web_set_state(2,0);scope.rack_web_set_state(3,0);scope.rack_web_set_state(5,.5);
  assert.ok([...visual(),...lights].every(Number.isFinite));
});

test("LifeForm PercussiveVibration preserves drum DSP, native control layout, and double-click reset ABI",()=>{
  const catalog=JSON.parse(fs.readFileSync(new URL("../public/dynamic-plugins/catalog.json",import.meta.url),"utf8")),
    definition=catalog.find(item=>item.key==="LifeFormModular/PercussiveVibration");
  assert.ok(definition);
  assert.equal(definition.localBuild.sourceCommit,"d1673014007bab2a17c74e1b061905bdc780f09d");
  assert.deepEqual(
    [definition.width,definition.params.length,definition.inputs.length,definition.outputs.length,definition.lights,definition.runtime.initialMemory],
    [420,26,15,5,0,4*1024*1024],
  );
  assert.deepEqual(
    definition.params.filter(param=>param.position).map(({id,position})=>[id,position.widget]),
    [[0,"LFMSnapKnob"],[1,"LFMKnob"],[2,"LFMKnob"],[4,"LFMTinyKnob"],[6,"LFMSliderWhite"],[7,"LFMSliderWhite"],[8,"LFMSliderWhite"],[10,"LFMKnob"],[11,"LFMKnob"],[12,"LFMKnob"],[13,"LFMTinyKnob"],[14,"LFMTinyKnob"],[15,"LFMTinyKnob"],[16,"LFMTinyKnob"],[17,"MS"],[18,"MS"],[19,"MS"],[20,"LFMKnob"],[21,"LFMTinyKnob"],[22,"LFMTinyKnob"],[23,"LFMKnob"],[24,"MS"],[25,"LFMKnob"]],
  );
  for(const asset of ["LFMKnob.svg","LFMTinyKnob.svg","LFMSlider.svg","LFMSliderWhiteHandle.svg","MS_0.svg","MS_1.svg"])
    assert.ok(fs.existsSync(new URL(`../public/rack-components/lifeform/${asset}`,import.meta.url)));
  const instantiate=()=>{
    const runtime=loadDynamicRuntime("LifeFormModular","PercussiveVibration"),
      inputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_input_buffer(),15*16*128),
      outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),5*16*128),
      process=(blocks=1)=>{for(let block=0;block<blocks;block++)runtime.rack_web_process(128,48000)},
      trigger=()=>{inputs.fill(10,7*128,8*128);runtime.rack_web_process(128,48000);inputs.fill(0,7*128,8*128)};
    for(const param of definition.params)runtime.rack_web_set_param(param.id,param.default);
    runtime.rack_web_set_input_connected(7,1);runtime.rack_web_set_input_channels(7,1);
    for(let output=0;output<5;output++)runtime.rack_web_set_output_connected(output,1);
    return{runtime,inputs,outputs,process,trigger};
  };
  const drum=instantiate();
  assert.deepEqual([drum.runtime.rack_web_param_count(),drum.runtime.rack_web_input_count(),drum.runtime.rack_web_output_count(),drum.runtime.rack_web_light_count()],[26,15,5,0]);
  drum.trigger();
  let oscillatorPeak=0,voicePeak=0,envelopePeak=0;
  for(let block=0;block<80;block++){
    drum.process();
    oscillatorPeak=Math.max(oscillatorPeak,...drum.outputs.slice(0,128).map(Math.abs));
    voicePeak=Math.max(voicePeak,...drum.outputs.slice(128,256).map(Math.abs));
    envelopePeak=Math.max(envelopePeak,...drum.outputs.slice(256,384).map(Math.abs));
  }
  assert.ok(oscillatorPeak>4.8&&voicePeak>3&&envelopePeak>8,`expected oscillator, drum voice, and envelope output; received ${oscillatorPeak}/${voicePeak}/${envelopePeak}`);
  const renderCutoff=cutoff=>{const instance=instantiate(),samples=[];instance.runtime.rack_web_set_param(20,cutoff);instance.trigger();for(let block=0;block<12;block++){instance.process();samples.push(...instance.outputs.slice(128,256))}return samples},
    bright=renderCutoff(.9),dark=renderCutoff(.05),
    difference=bright.reduce((sum,value,index)=>sum+Math.abs(value-dark[index]),0);
  assert.ok(difference>10,`expected the cutoff knob to change the drum waveform, received ${difference}`);
  for(const [id,value,initial] of [[0,4,8],[6,0,.5],[20,0,.9],[24,1,0]]){
    drum.runtime.rack_web_set_param(id,value);drum.runtime.rack_web_reset_param(id,initial);
    assert.ok(Math.abs(drum.runtime.rack_web_get_param(id)-initial)<1e-6);
  }
  drum.runtime.rack_web_set_param(2,.8);drum.runtime.rack_web_reset_param(2,0);
  assert.ok(Math.abs(drum.runtime.rack_web_get_param(2)-.1)<1e-6);
  assert.ok([...drum.outputs,...bright,...dark].every(Number.isFinite));
});

test("LifeForm ComplexOsc preserves dual oscillator DSP, V/Oct, native rotating controls, and double-click reset ABI",()=>{
  const catalog=JSON.parse(fs.readFileSync(new URL("../public/dynamic-plugins/catalog.json",import.meta.url),"utf8")),
    definition=catalog.find(item=>item.key==="LifeFormModular/ComplexOsc");
  assert.ok(definition);
  assert.equal(definition.localBuild.sourceCommit,"d1673014007bab2a17c74e1b061905bdc780f09d");
  assert.deepEqual(
    [definition.width,definition.params.length,definition.inputs.length,definition.outputs.length,definition.lights,definition.runtime.initialMemory],
    [270,20,9,3,0,4*1024*1024],
  );
  assert.ok(definition.params.every(param=>param.position&&["LFMKnob","LFMSnapKnob","LFMTinyKnob"].includes(param.position.widget)));
  assert.deepEqual(definition.params.filter(param=>param.snap).map(param=>param.id),[3,14,16,17]);
  const instantiate=()=>{
    const runtime=loadDynamicRuntime("LifeFormModular","ComplexOsc"),
      inputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_input_buffer(),9*16*128),
      outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),3*16*128),
      render=(blocks=64)=>{const samples=[[],[],[]];for(let block=0;block<blocks;block++){runtime.rack_web_process(128,48000);for(let output=0;output<3;output++)samples[output].push(...outputs.slice(output*128,(output+1)*128))}return samples};
    for(const param of definition.params)runtime.rack_web_set_param(param.id,param.default);
    for(let output=0;output<3;output++)runtime.rack_web_set_output_connected(output,1);
    return{runtime,inputs,outputs,render};
  };
  const crossings=values=>values.slice(1).reduce((count,value,index)=>count+(values[index]<=0&&value>0?1:0),0),
    energy=values=>values.reduce((sum,value)=>sum+Math.abs(value),0),
    base=instantiate(),baseSamples=base.render();
  assert.deepEqual([base.runtime.rack_web_param_count(),base.runtime.rack_web_input_count(),base.runtime.rack_web_output_count(),base.runtime.rack_web_light_count()],[20,9,3,0]);
  assert.ok(baseSamples.every(samples=>Math.max(...samples.map(Math.abs))>4.8));
  const octave=instantiate();octave.runtime.rack_web_set_input_connected(0,1);octave.runtime.rack_web_set_input_channels(0,1);octave.inputs.fill(1,0,128);const octaveSamples=octave.render();
  assert.ok(crossings(octaveSamples[0])>crossings(baseSamples[0])*1.9&&crossings(octaveSamples[0])<crossings(baseSamples[0])*2.1);
  const fm=instantiate();fm.runtime.rack_web_set_param(2,1);const fmSamples=fm.render();
  assert.ok(crossings(fmSamples[0])>crossings(baseSamples[0])*1.9);
  const crossed=instantiate();crossed.runtime.rack_web_set_param(11,1);const crossedSamples=crossed.render();
  assert.ok(Math.abs(energy(crossedSamples[0])-energy(baseSamples[0]))>1000);
  for(const [id,value,initial] of [[0,.8,0],[3,2,0],[14,12,0],[18,1,0]]){
    base.runtime.rack_web_set_param(id,value);base.runtime.rack_web_reset_param(id,initial);
    assert.equal(base.runtime.rack_web_get_param(id),initial);
  }
  assert.ok([...baseSamples,...octaveSamples,...fmSamples,...crossedSamples].flat().every(Number.isFinite));
});

test("Lomas GateSequencer preserves native rubber controls, short and long presses, clocked gates, state, lights, and double-click reset ABI",()=>{
  const catalog=JSON.parse(fs.readFileSync(new URL("../public/dynamic-plugins/catalog.json",import.meta.url),"utf8")),
    definition=catalog.find(item=>item.key==="LomasModules/GateSequencer");
  assert.ok(definition);
  assert.equal(definition.localBuild.sourceCommit,"1def9f3ee461e7736452ee9e06fa1a25c191b558");
  assert.deepEqual(
    [definition.width,definition.params.length,definition.inputs.length,definition.outputs.length,definition.lights,definition.lightWidgets.length,definition.stateKeys.length],
    [120,28,2,1,72,24,262],
  );
  assert.deepEqual(definition.params.filter(param=>param.position).map(({id,position})=>[id,position.widget]),[
    ...Array.from({length:4},(_,id)=>[id,"RubberButton"]),
    ...Array.from({length:16},(_,index)=>[8+index,"RubberButton"]),
    ...Array.from({length:4},(_,index)=>[24+index,"RubberButton"]),
  ]);
  assert.ok(definition.params.filter(param=>param.position).every(param=>param.button&&param.snap));
  assert.deepEqual(definition.inputs.map(({name,kind,position})=>[name,kind,position]),[
    ["Clock","gate",{x:22.5,y:334.964,centered:true,widget:"PJ301MPort"}],
    ["Reset","gate",{x:60,y:334.964,centered:true,widget:"PJ301MPort"}],
  ]);
  assert.deepEqual(definition.outputs.map(({name,kind,position})=>[name,kind,position]),[
    ["Gate","gate",{x:97.5,y:334.964,centered:true,widget:"PJ301MPort"}],
  ]);
  for(const light of definition.lightWidgets){
    const param=definition.params.find(item=>item.position?.x===light.position.x&&item.position?.y===light.position.y);
    assert.ok(param,`light ${light.id} does not share its button center`);
    assert.equal(light.widget,"RubberButtonLed<RedGreenBlueLight>");
  }
  for(const asset of ["RubberButton.svg","RubberButton1.svg","RubberSmallButton.svg","RubberSmallButton1.svg","RoundGrayKnob.svg","RoundSmallGrayKnob.svg","RoundBigGrayKnob.svg"])
    assert.ok(fs.existsSync(new URL(`../public/rack-components/lomas/${asset}`,import.meta.url)));
  const instantiate=()=>{
    const runtime=loadDynamicRuntime("LomasModules","GateSequencer"),
      inputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_input_buffer(),2*16*128),
      outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),16*128),
      lights=new Float32Array(runtime.memory.buffer,runtime.rack_web_light_buffer(),72),
      process=(blocks=1)=>{for(let block=0;block<blocks;block++)runtime.rack_web_process(128,48000)},
      setInput=(port,value)=>inputs.fill(value,port*128,(port+1)*128),
      snapshot=()=>{const length=runtime.rack_web_snapshot_state_json();return JSON.parse(new TextDecoder().decode(new Uint8Array(runtime.memory.buffer,runtime.rack_web_snapshot_state_buffer(),length)))},
      press=(id,blocks=8)=>{runtime.rack_web_set_param(id,1);process(blocks);runtime.rack_web_set_param(id,0);process(8)};
    for(const param of definition.params)runtime.rack_web_set_param(param.id,param.default);
    for(let input=0;input<2;input++){runtime.rack_web_set_input_connected(input,1);runtime.rack_web_set_input_channels(input,1)}
    runtime.rack_web_set_output_connected(0,1);
    process(8);
    return{runtime,inputs,outputs,lights,process,setInput,snapshot,press};
  };
  const sequencer=instantiate();
  assert.deepEqual(
    [sequencer.runtime.rack_web_param_count(),sequencer.runtime.rack_web_input_count(),sequencer.runtime.rack_web_output_count(),sequencer.runtime.rack_web_light_count(),sequencer.runtime.rack_web_message_capacity()],
    [28,2,1,72,32768],
  );
  sequencer.press(9);
  assert.equal(sequencer.snapshot().gates[1],1);
  sequencer.setInput(0,10);sequencer.runtime.rack_web_process(1,48000);
  assert.equal(sequencer.outputs[0],10);
  sequencer.setInput(0,0);sequencer.runtime.rack_web_process(1,48000);
  assert.equal(sequencer.outputs[0],0);
  sequencer.press(11,200);
  assert.equal(sequencer.snapshot().len[0],3);
  sequencer.press(25);
  sequencer.setInput(1,10);sequencer.runtime.rack_web_process(1,48000);
  sequencer.setInput(1,0);sequencer.process();
  for(let pulse=0;pulse<16;pulse++){
    sequencer.setInput(0,10);sequencer.runtime.rack_web_process(1,48000);
    sequencer.setInput(0,0);sequencer.runtime.rack_web_process(1,48000);
  }
  assert.equal(sequencer.snapshot().patternIndex,1);
  const state=sequencer.snapshot(),encoded=new TextEncoder().encode(JSON.stringify(state)),restored=instantiate(),
    target=new Uint8Array(restored.runtime.memory.buffer,restored.runtime.rack_web_state_buffer(encoded.length),encoded.length);
  target.set(encoded);
  assert.equal(restored.runtime.rack_web_commit_state_json(encoded.length),1);
  assert.deepEqual(
    [restored.snapshot().patternIndex,restored.snapshot().gates[1],restored.snapshot().len[0],restored.snapshot().reset_mode],
    [1,1,3,1],
  );
  for(const param of definition.params){
    const changed=param.default===param.max?param.min:param.max;
    restored.runtime.rack_web_set_param(param.id,changed);
    restored.runtime.rack_web_reset_param(param.id,param.default);
    assert.ok(Math.abs(restored.runtime.rack_web_get_param(param.id)-param.default)<1e-6,`param ${param.id} did not reset`);
  }
  restored.process(8);
  assert.ok([...sequencer.outputs,...sequencer.lights,...restored.outputs,...restored.lights].every(Number.isFinite));
  assert.ok(Math.max(...sequencer.lights)>0);
});

