test("MADZINE Weiii Documenta records and loops stereo audio with its exact waveform display and reset ABI",()=>{
  const catalog=JSON.parse(fs.readFileSync(new URL("../public/dynamic-plugins/catalog.json",import.meta.url),"utf8")),
    definition=catalog.find(item=>item.key==="MADZINE/WeiiiDocumenta");
  assert.ok(definition);
  assert.equal(definition.localBuild.sourceCommit,"f8f8a93c0ec59255984ff2c3e56e080927b80522");
  assert.deepEqual([definition.width,definition.params.length,definition.inputs.length,definition.outputs.length,definition.lights],[180,21,15,5,4]);
  assert.deepEqual(definition.params.filter(param=>param.snap).map(param=>param.id),[5,12,18,19,20]);
  assert.deepEqual(definition.params.filter(param=>param.button).map(param=>param.id),[5,18,19,20]);
  assert.deepEqual(definition.params.filter(param=>!param.hidden).map(param=>param.position?.widget),[
    "MediumGrayKnob","Trimpot","WhiteKnob","Trimpot","VCVButton","MediumGrayKnob","Trimpot",
    "LargeWhiteKnob","LargeWhiteKnob","LargeWhiteKnob","MediumGrayKnob","MediumGrayKnob","MediumGrayKnob",
    "WhiteKnob","Trimpot","MediumGrayKnob","Trimpot","VCVButton","VCVButton","VCVButton",
  ]);
  assert.ok([0,1,3,4].every(id=>definition.outputs[id].kind==="audio"));
  assert.equal(definition.outputs[2].kind,"cv");
  assert.ok([0,1,9,10].every(id=>definition.inputs[id].kind==="audio"));
  assert.deepEqual(definition.runtime.visuals,[{kind:"madzine-waveform",points:170,maxSlices:64,maxVoices:8,loopEndParam:4,x:5,y:38,width:170,height:47}]);
  const runtime=loadDynamicRuntime("MADZINE","WeiiiDocumenta"),
    inputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_input_buffer(),15*16*128),
    outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),5*16*128),
    lights=new Float32Array(runtime.memory.buffer,runtime.rack_web_light_buffer(),4),
    defaults=definition.params.map(param=>param.default),
    pulse=(id)=>{runtime.rack_web_set_param(id,1);runtime.rack_web_process(1,48000);runtime.rack_web_set_param(id,0);runtime.rack_web_process(1,48000)};
  assert.deepEqual([runtime.rack_web_param_count(),runtime.rack_web_input_count(),runtime.rack_web_output_count(),runtime.rack_web_light_count(),runtime.rack_web_visual_count()],[21,15,5,4,420]);
  for(const param of definition.params)runtime.rack_web_set_param(param.id,param.default);
  for(const input of [0,1]){runtime.rack_web_set_input_connected(input,1);runtime.rack_web_set_input_channels(input,1)}
  for(let output=0;output<5;output++)runtime.rack_web_set_output_connected(output,1);
  pulse(18);assert.equal(lights[0],1);
  let frame=0;
  for(let block=0;block<12;block++){
    for(let index=0;index<128;index++,frame++){inputs[index]=4*Math.sin(frame*.08);inputs[128+index]=3*Math.cos(frame*.06)}
    runtime.rack_web_process(128,48000);
  }
  pulse(18);assert.equal(lights[0],0);
  pulse(19);assert.deepEqual([...lights.slice(1,3)],[0,1]);
  const peaks=[0,0,0,0,0];
  for(let block=0;block<8;block++){
    runtime.rack_web_process(128,48000);
    for(let output=0;output<5;output++)for(let index=0;index<128;index++)peaks[output]=Math.max(peaks[output],Math.abs(outputs[output*128+index]));
  }
  assert.ok(peaks[0]>1&&peaks[1]>1,`recorded stereo playback stayed silent: ${peaks}`);
  assert.ok(peaks[3]>1&&peaks[4]>1,`stereo send stayed silent: ${peaks}`);
  const visual=Array.from(new Float32Array(runtime.memory.buffer,runtime.rack_web_visual_buffer(),runtime.rack_web_visual_count()));
  assert.ok(visual[0]>=1536);assert.equal(visual[1],60*48000);assert.ok((Math.round(visual[2])&4)!==0);
  assert.ok(visual.slice(8,178).some(value=>Math.abs(value)>1));
  assert.ok(visual.slice(178,348).some(value=>Math.abs(value)>1));
  assert.ok(visual.slice(348,412).some(value=>value>=0));
  assert.ok(visual.slice(412).some(value=>value>=0));
  runtime.rack_web_set_param(4,.25);runtime.rack_web_reset_param(4,1);assert.equal(runtime.rack_web_get_param(4),1);
  for(const id of [0,2,5,8,12,18,19,20]){
    const param=definition.params[id];runtime.rack_web_set_param(id,param.default===param.max?param.min:param.max);
    runtime.rack_web_reset_param(id,param.default);
    assert.ok(Math.abs(runtime.rack_web_get_param(id)-defaults[id])<1e-6,`param ${id} did not reset`);
  }
  assert.ok([...outputs,...lights,...visual].every(Number.isFinite));
});

