test("ML Quantizer independently blends both polyphonic lanes between semitone quantization and dry pitch",()=>{
  const catalog=JSON.parse(fs.readFileSync(new URL("../public/dynamic-plugins/catalog.json",import.meta.url),"utf8")),
    definition=catalog.find(item=>item.key==="ML_modules/Quantizer");
  assert.ok(definition);
  assert.equal(definition.localBuild.sourceCommit,"05ac273285dca1da828deca5aba37c0b7df0fbbd");
  assert.deepEqual([definition.width,definition.params.length,definition.inputs.length,definition.outputs.length,definition.lights],[45,2,2,2,0]);
  assert.deepEqual(definition.params.map(param=>({id:param.id,min:param.min,max:param.max,default:param.default,position:param.position})),[
    {id:0,min:-1,max:1,default:0,position:{x:9,y:60,widget:"SmallBlueMLKnob"}},
    {id:1,min:-1,max:1,default:0,position:{x:9,y:203,widget:"SmallBlueMLKnob"}},
  ]);
  assert.deepEqual(definition.inputs.map(port=>port.kind),["cv","cv"]);
  assert.deepEqual(definition.outputs.map(port=>port.kind),["cv","cv"]);
  const runtime=loadDynamicRuntime("ML_modules","Quantizer"),inputCount=2,outputCount=2,
    inputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_input_buffer(),inputCount*16*128),
    outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),outputCount*16*128),
    read=(output,channel)=>outputs[(channel*outputCount+output)*128],
    pitch=[.04,.12,-.12,1.19],
    expected=[0,1/12,-1/12,1+2/12];
  assert.deepEqual([runtime.rack_web_param_count(),runtime.rack_web_input_count(),runtime.rack_web_output_count(),runtime.rack_web_light_count()],[2,2,2,0]);
  for(let input=0;input<2;input++){runtime.rack_web_set_input_connected(input,1);runtime.rack_web_set_input_channels(input,4)}
  for(let output=0;output<2;output++)runtime.rack_web_set_output_connected(output,1);
  for(let channel=0;channel<4;channel++){
    inputs[(channel*inputCount)*128]=pitch[channel];
    inputs[(channel*inputCount+1)*128]=pitch[3-channel];
  }
  runtime.rack_web_set_param(0,0);
  runtime.rack_web_set_param(1,1);
  runtime.rack_web_process(1,48000);
  assert.equal(runtime.rack_web_get_output_channels(0),4);
  assert.equal(runtime.rack_web_get_output_channels(1),4);
  for(let channel=0;channel<4;channel++){
    assert.ok(Math.abs(read(0,channel)-expected[channel])<1e-6,`quantized channel ${channel}`);
    assert.ok(Math.abs(read(1,channel)-pitch[3-channel])<1e-6,`dry channel ${channel}`);
  }
  runtime.rack_web_set_param(0,-1);
  runtime.rack_web_process(1,48000);
  for(let channel=0;channel<4;channel++)assert.ok(Math.abs(read(0,channel)-(2*expected[channel]-pitch[channel]))<1e-6);
  for(const param of definition.params){
    runtime.rack_web_set_param(param.id,param.max);
    runtime.rack_web_reset_param(param.id,param.default);
    assert.equal(runtime.rack_web_get_param(param.id),param.default);
  }
  assert.ok(outputs.every(Number.isFinite));
});

