  assert.deepEqual(definition.params.map(param=>param.position.widget),[
    "RedLargeKnob","RedSmallKnob","BlueSmallKnob","BlueSmallKnob","VioMSwitch","BlueSmallKnob","VioM2Switch",
  ]);
