  const runtime=loadDynamicRuntime("Minilab3","MiniLab"),outputCount=runtime.rack_web_output_count(),
    outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),outputCount*16*128),
    process=()=>runtime.rack_web_process(128,48000),
    sample=id=>outputs[id*128+127];
  assert.deepEqual([runtime.rack_web_param_count(),runtime.rack_web_input_count(),outputCount,runtime.rack_web_light_count()],[0,1,17,1]);
  process();
  assert.deepEqual([sample(0),sample(1),sample(2),sample(3),sample(4)],[5,0,-5,0,0]);
  runtime.rack_web_midi_push(3,0xb0,80,127);
  runtime.rack_web_midi_push(3,0xb0,1,64);
  runtime.rack_web_midi_push(3,0xb0,102,65);
  runtime.rack_web_midi_push(3,0xe0,0,127);
  runtime.rack_web_midi_push(3,0xa0,60,32);
