test("TriggerFish VDPO tracks V/Oct and its analog VCA responds monotonically to control voltage",()=>{
  const renderVdpo=pitch=>{
      const runtime=loadDynamicRuntime("TriggerFish-Elements","TfVDPO"),
        inputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_input_buffer(),3*16*128),
        outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),16*128);
      runtime.rack_web_set_input_connected(0,1);
      runtime.rack_web_set_input_channels(0,1);
      runtime.rack_web_set_output_connected(0,1);
      runtime.rack_web_set_param(3,1);
      runtime.rack_web_set_param(4,1);
      let crossings=0,peak=0,previous=0;
      for(let block=0;block<500;block++){
        inputs.fill(pitch,0,128);
        runtime.rack_web_process(128,48000);
        if(block<100)continue;
        for(let frame=0;frame<128;frame++){
          const value=outputs[frame];
          assert.ok(Number.isFinite(value));
          if(previous<=0&&value>0)crossings++;
          peak=Math.max(peak,Math.abs(value));
          previous=value;
        }
      }
      return{crossings,peak};
    },
    base=renderVdpo(0),
    octave=renderVdpo(1);
  assert.ok(base.peak>.1&&octave.peak>.1);
  assert.ok(octave.crossings>base.crossings*1.9&&octave.crossings<base.crossings*2.1,`VDPO crossings ${base.crossings}/${octave.crossings}`);

  const renderVca=cv=>{
      const runtime=loadDynamicRuntime("TriggerFish-Elements","TfVCA"),
        inputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_input_buffer(),3*16*128),
        outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),16*128);
      for(const port of [0,1]){
        runtime.rack_web_set_input_connected(port,1);
        runtime.rack_web_set_input_channels(port,1);
      }
      runtime.rack_web_set_output_connected(0,1);
      runtime.rack_web_set_param(3,0);
      let energy=0,samples=0;
      for(let block=0;block<100;block++){
        for(let frame=0;frame<128;frame++){
          inputs[frame]=5*Math.sin(2*Math.PI*220*(block*128+frame)/48000);
          inputs[128+frame]=cv;
        }
        runtime.rack_web_process(128,48000);
        if(block<20)continue;
        for(const value of outputs.slice(0,128)){
          assert.ok(Number.isFinite(value));
          energy+=value*value;
          samples++;
        }
      }
      return Math.sqrt(energy/samples);
    },
    closed=renderVca(0),
    half=renderVca(5),
    open=renderVca(10);
  assert.ok(closed<1e-6,`closed VCA RMS ${closed}`);
  assert.ok(half>1&&open>half*1.5,`VCA RMS ${closed}/${half}/${open}`);
});

