test("WrongPeople MIDIPlayer parses an uploaded Standard MIDI File and emits pitch, gate, velocity, retrigger, play, and stop signals",()=>{
  const runtime=loadDynamicRuntime("WrongPeople","MIDIPlayer"),
    midi=Uint8Array.from([
      0x4d,0x54,0x68,0x64,0x00,0x00,0x00,0x06,0x00,0x00,0x00,0x01,0x01,0xe0,
      0x4d,0x54,0x72,0x6b,0x00,0x00,0x00,0x14,
      0x00,0xff,0x51,0x03,0x07,0xa1,0x20,
      0x00,0x90,0x48,0x64,
      0x83,0x60,0x80,0x48,0x00,
      0x00,0xff,0x2f,0x00,
    ]),
    asset=new Float32Array(runtime.memory.buffer,runtime.rack_web_asset_buffer(),midi.length),
    outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),26*16*128),
    output=port=>outputs[port*128];
  asset.set(midi);
  runtime.rack_web_commit_asset(midi.length,1,0);
  for(let port=0;port<26;port++)runtime.rack_web_set_output_connected(port,1);
  runtime.rack_web_set_param(0,1);
  runtime.rack_web_process(1,48000);
  runtime.rack_web_set_param(0,0);
  assert.equal(output(0),10);
  assert.ok(Math.abs(output(2)-1)<1e-6,`pitch ${output(2)}`);
  assert.equal(output(8),10);
  assert.ok(Math.abs(output(14)-1000/127)<1e-5,`velocity ${output(14)}`);
  assert.equal(output(20),10);
  assert.ok(outputs.every(Number.isFinite));

  runtime.rack_web_set_param(1,1);
  runtime.rack_web_process(1,48000);
  runtime.rack_web_set_param(1,0);
  assert.equal(output(1),10);
  assert.equal(output(8),0);

  runtime.rack_web_set_param(0,1);
  runtime.rack_web_process(1,48000);
  runtime.rack_web_set_param(0,0);
  for(let block=0;block<190;block++)runtime.rack_web_process(128,48000);
  assert.equal(output(8),0);
  assert.ok(outputs.every(Number.isFinite));
});

test("WrongPeople Tourette preserves its ABI and records, stores, and replays detected audio shots",()=>{
  const catalog=JSON.parse(fs.readFileSync(new URL("../public/dynamic-plugins/catalog.json",import.meta.url),"utf8")),
    definition=catalog.find(item=>item.key==="WrongPeople/Tourette");
  assert.ok(definition);
  assert.equal(definition.localBuild.sourceCommit,"74c8d2bd7246813ff60887e0bd9068a84b7b21b3");
  assert.deepEqual([definition.params.length,definition.inputs.length,definition.outputs.length,definition.lights,definition.lightWidgets.length],[10,3,2,48,16]);
  assert.deepEqual(definition.inputs.map(({kind})=>kind),["audio","audio","gate"]);
  assert.deepEqual(definition.outputs.map(({kind})=>kind),["audio","audio"]);
  assert.ok([...definition.params,...definition.inputs,...definition.outputs,...definition.lightWidgets].every(control=>control.position));

  const runtime=loadDynamicRuntime("WrongPeople","Tourette"),
    inputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_input_buffer(),3*16*128),
    outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),2*16*128),
    lights=new Float32Array(runtime.memory.buffer,runtime.rack_web_light_buffer(),48),
    process=(frames,valueA=0,trigger=0)=>{
      for(let done=0;done<frames;done+=128){
        const count=Math.min(128,frames-done);
        inputs.fill(valueA,0,128);
        inputs.fill(trigger,2*128,3*128);
        runtime.rack_web_process(count,48000);
      }
    };
  assert.deepEqual(
    [runtime.rack_web_param_count(),runtime.rack_web_input_count(),runtime.rack_web_output_count(),runtime.rack_web_light_count()],
    [10,3,2,48],
  );
  for(const param of definition.params)runtime.rack_web_set_param(param.id,param.default);
  runtime.rack_web_set_param(3,.01);
  runtime.rack_web_set_param(4,1);
  runtime.rack_web_set_param(5,0);
  runtime.rack_web_set_input_connected(0,1);
  runtime.rack_web_set_input_channels(0,1);
  runtime.rack_web_set_input_connected(2,1);
  runtime.rack_web_set_input_channels(2,1);
  runtime.rack_web_set_output_connected(0,1);
  process(1200,2);
  process(600,0);
  assert.ok(lights.some((value,index)=>index%3===0&&value>.5),`full lights ${[...lights]}`);

  process(1,0,10);
  process(1,0,0);
  let peak=0,nonzero=0;
  for(let block=0;block<4;block++){
    process(128);
    for(const value of outputs.slice(0,128)){
      assert.ok(Number.isFinite(value));
      peak=Math.max(peak,Math.abs(value));
      nonzero+=Math.abs(value)>1e-4;
    }
  }
  assert.ok(peak>1.9&&peak<2.1,`replayed peak ${peak}`);
  assert.ok(nonzero>300,`replayed samples ${nonzero}`);
  assert.ok(outputs.every(Number.isFinite));
});

