test("WrongPeople Lua executes an uploaded script and reports syntax errors without trapping",()=>{
  const runtime=loadDynamicRuntime("WrongPeople","Lua"),
    inputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_input_buffer(),8*16*128),
    outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),8*16*128),
    lights=new Float32Array(runtime.memory.buffer,runtime.rack_web_light_buffer(),2),
    upload=source=>{
      const bytes=new TextEncoder().encode(source),
        asset=new Float32Array(runtime.memory.buffer,runtime.rack_web_asset_buffer(),bytes.length);
      asset.set(bytes);
      runtime.rack_web_commit_asset(bytes.length,1,0);
    };
  runtime.rack_web_set_input_connected(0,1);
  runtime.rack_web_set_input_channels(0,1);
  runtime.rack_web_set_output_connected(0,1);
  upload("function process(sampleRate, sampleTime)\n  setChannels(0, 1)\n  setVoltage(0, getVoltage(0) * 2)\nend\n");
  inputs[0]=.75;
  assert.doesNotThrow(()=>runtime.rack_web_process(1,48000));
  assert.deepEqual([...lights],[1,0],"valid Lua script should load");
  assert.ok(Math.abs(outputs[0]-1.5)<1e-6,`Lua output ${outputs[0]}, lights ${[...lights]}`);

  assert.doesNotThrow(()=>upload("function process(\n"));
  assert.doesNotThrow(()=>runtime.rack_web_process(1,48000));
  assert.deepEqual([...lights],[0,1]);
  assert.ok(outputs.every(Number.isFinite));
});

test("tnn1t1s Ghost drum voices preserve their ABI and produce finite triggered audio",()=>{
  const catalog=JSON.parse(fs.readFileSync(new URL("../public/dynamic-plugins/catalog.json",import.meta.url),"utf8")),
    sourceCommit="db01f822804f370fe2c801d610fd261a851c31b9",
    expected={
      Kck:{counts:[9,12,1,0],voices:[[0,0]]},
      Snr:{counts:[4,7,1,0],voices:[[0,0]]},
      ChhOhh:{counts:[8,10,2,0],voices:[[0,0],[1,1]]},
      RimClap:{counts:[4,7,2,0],voices:[[0,0],[1,1]]},
      Toms:{counts:[9,14,3,0],voices:[[0,0],[1,1],[2,2]]},
      CrashRide:{counts:[8,9,2,0],voices:[[0,0],[1,1]]},
    };
  for(const [model,{counts,voices}] of Object.entries(expected)){
    const definition=catalog.find(item=>item.key===`tnn1t1s-ghost/${model}`);
    assert.ok(definition,model);
    assert.equal(definition.localBuild.sourceCommit,sourceCommit,model);
    assert.deepEqual(
      [definition.params.length,definition.inputs.length,definition.outputs.length,definition.lights],
      counts,
      model,
    );
    const contextMenuParams=new Set(["ChhOhh","CrashRide"].includes(model)?[2,6]:[]);
    assert.ok(definition.params.filter(param=>!contextMenuParams.has(param.id)).every(param=>param.position),`${model} panel param geometry`);
    assert.ok(definition.params.filter(param=>contextMenuParams.has(param.id)).every(param=>!param.position),`${model} context-menu param geometry`);
    assert.ok([...definition.inputs,...definition.outputs].every(port=>port.position),`${model} port geometry`);
    if(model==="Kck"){
      assert.deepEqual(definition.params[0].position,{x:30.632,y:89.075,centered:true,widget:"RoundBlackKnob"},"NanoSVG 75 DPI knob center");
      assert.deepEqual(definition.inputs[0].position,{x:42.18,y:333.661,centered:true,widget:"PJ301MPort"},"NanoSVG trigger-jack center");
      assert.deepEqual(definition.outputs[0].position,{x:197.82,y:333.661,centered:true,widget:"PJ301MPort"},"NanoSVG output-jack center");
    }
    assert.ok(definition.outputs.every(output=>output.kind==="audio"),`${model} audio metadata`);
    if(model==="CrashRide")assert.ok(definition.runtime.initialMemory>=8*1024*1024,"CrashRide ROM memory");

    for(const [triggerId,outputId] of voices){
      const runtime=loadDynamicRuntime("tnn1t1s-ghost",model),
        inputCount=runtime.rack_web_input_count(),
        outputCount=runtime.rack_web_output_count(),
        inputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_input_buffer(),inputCount*16*128),
        outputs=new Float32Array(runtime.memory.buffer,runtime.rack_web_output_buffer(),outputCount*16*128);
      assert.deepEqual(
        [runtime.rack_web_param_count(),inputCount,outputCount,runtime.rack_web_light_count()],
        counts,
        model,
      );
      for(const param of definition.params){
        assert.ok(Math.abs(runtime.rack_web_get_param(param.id)-param.default)<1e-5,`${model} default ${param.id}`);
        runtime.rack_web_set_param(param.id,param.min);
        runtime.rack_web_reset_param(param.id,param.default);
        assert.ok(Math.abs(runtime.rack_web_get_param(param.id)-param.default)<1e-5,`${model} reset ${param.id}`);
      }
      runtime.rack_web_set_input_connected(triggerId,1);
      runtime.rack_web_set_input_channels(triggerId,1);
      runtime.rack_web_set_output_connected(outputId,1);
      runtime.rack_web_process(8,48000);
      inputs.fill(10,triggerId*128,(triggerId+1)*128);
      runtime.rack_web_process(1,48000);
      inputs.fill(0,triggerId*128,(triggerId+1)*128);
      let peak=0,nonzero=0;
      for(let block=0;block<80;block++){
        runtime.rack_web_process(128,48000);
        for(let frame=0;frame<128;frame++){
          const value=outputs[outputId*128+frame];
          assert.ok(Number.isFinite(value),`${model} ${triggerId}->${outputId} finite`);
          peak=Math.max(peak,Math.abs(value));
          nonzero+=Math.abs(value)>1e-5;
        }
      }
      assert.ok(peak>.05,`${model} ${triggerId}->${outputId} peak ${peak}`);
      assert.ok(nonzero>100,`${model} ${triggerId}->${outputId} samples ${nonzero}`);
    }
  }
});
